mapper.select:
SELECT id, tool_invocation_id, run_id, request_id, session_id, tool_call_id, status, error_msg,
       title, mode, primary_file_name, preview_url, download_url, open_in_panel, salvaged, created_at, updated_at
FROM ai_agent_tool_output_canvas_publish
WHERE request_id = #{requestId}
  AND tool_call_id = #{toolCallId}
LIMIT 1
